import java.util.Arrays;
import java.util.Objects;

public final class BubbleSort {
    private BubbleSort() {
    }

    public static int[] sortedCopy(int[] numbers) {
        int[] source = Objects.requireNonNull(numbers, "numbers must not be null");
        int[] copy = Arrays.copyOf(source, source.length);
        sort(copy);
        return copy;
    }

    public static void sort(int[] numbers) {
        Objects.requireNonNull(numbers, "numbers must not be null");

        int lastUnsortedIndex = numbers.length - 1;
        while (lastUnsortedIndex > 0) {
            lastUnsortedIndex = moveLargestValueToBoundary(numbers, lastUnsortedIndex);
        }
    }

    private static int moveLargestValueToBoundary(int[] numbers, int boundaryIndex) {
        int lastSwapIndex = 0;

        for (int currentIndex = 0; currentIndex < boundaryIndex; currentIndex++) {
            int nextIndex = currentIndex + 1;

            if (!isOutOfOrder(numbers, currentIndex, nextIndex)) {
                continue;
            }

            swap(numbers, currentIndex, nextIndex);
            lastSwapIndex = currentIndex;
        }

        return lastSwapIndex;
    }

    private static boolean isOutOfOrder(int[] numbers, int firstIndex, int secondIndex) {
        return numbers[firstIndex] > numbers[secondIndex];
    }

    private static void swap(int[] numbers, int firstIndex, int secondIndex) {
        int temp = numbers[firstIndex];
        numbers[firstIndex] = numbers[secondIndex];
        numbers[secondIndex] = temp;
    }
}

import java.util.Arrays;

public final class BubbleSortDemo {
    private static final int[] SAMPLE_NUMBERS = {64, 34, 25, 12, 22, 11, 90};

    private BubbleSortDemo() {
    }

    public static void main(String[] args) {
        int[] sortedNumbers = BubbleSort.sortedCopy(SAMPLE_NUMBERS);

        System.out.println("Sorted array: ");
        System.out.println(Arrays.toString(sortedNumbers));
    }
}
